const c = $input.first().json;

const list = (value, sep) => String(value || "").split(sep || ",").map(s => s.trim()).filter(Boolean);

const LOCATION_TYPES = ["Remote", "Hybrid", "In-Person"];
const EXPERIENCE_LEVELS = ["Entry", "Junior", "Mid", "Senior", "Executive"];
const JOB_TYPES = ["Full Time", "Part Time", "Contract", "Internship"];

const normalise = (value, allowed) => {
  const wanted = String(value).toLowerCase().replace(/[\s_-]+/g, " ").trim();
  return allowed.find(a => a.toLowerCase() === wanted) || null;
};

const payload = {
  postedWithinDays: 1,
  includeJobsWithoutSalary: true,
  maxResults: Math.max(1, Number(c.maxResults) || 25)
};

const keywords = list(c.keywords);
if (keywords.length) payload.keywords = keywords;

const jobTitles = list(c.jobTitles);
if (jobTitles.length) payload.jobTitles = jobTitles;

const locations = list(c.locations, ";");
if (locations.length) payload.locations = locations;

const locationTypes = list(c.locationTypes).map(v => normalise(v, LOCATION_TYPES)).filter(Boolean);
if (locationTypes.length) payload.locationTypes = locationTypes;

const jobTypes = list(c.jobTypes).map(v => normalise(v, JOB_TYPES)).filter(Boolean);
if (jobTypes.length) payload.jobTypes = jobTypes;

const experienceLevels = list(c.experienceLevels).map(v => normalise(v, EXPERIENCE_LEVELS)).filter(Boolean);
if (experienceLevels.length) payload.experienceLevels = experienceLevels;

const visa = String(c.visaSponsorship || "any").toLowerCase().trim();
if (visa === "yes" || visa === "no") payload.visaSponsorship = visa;

const salaryMin = Number(c.salaryMin);
if (salaryMin > 0) {
  payload.salaryMin = salaryMin;
  payload.currency = String(c.currency || "USD").toUpperCase().trim();
}

if (!payload.keywords && !payload.jobTitles) {
  throw new Error("Open the Search Settings node and fill in Keywords or Job Titles before running.");
}

return [{ json: { payload } }];

