const cfg = $("Search Settings").first().json;

const list = (value) => String(value || "").toLowerCase().split(",").map(s => s.trim()).filter(Boolean);
const wantTitles = list(cfg.jobTitles);
const wantKeywords = list(cfg.keywords);
const salaryTarget = Number(cfg.salaryMin) || 0;
const preferRemote = String(cfg.preferRemote).toLowerCase() === "true";
const needsVisa = String(cfg.visaSponsorship).toLowerCase() === "yes";

const results = [];

for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.jobTitle) continue;

  const title = String(j.jobTitle).toLowerCase();
  const skills = Array.isArray(j.skills) ? j.skills.join(" ") : "";
  const tech = Array.isArray(j.technologies) ? j.technologies.join(" ") : "";
  const blob = (title + " " + String(j.descriptionText || "") + " " + skills + " " + tech).toLowerCase();
  const sr = j.salaryRange || {};
  const salaryFloor = Number(sr.min) || 0;

  let score = 0;
  const reasons = [];

  if (wantTitles.length && wantTitles.some(t => title.includes(t))) {
    score += 3;
    reasons.push("title match");
  }

  const hits = wantKeywords.filter(k => blob.includes(k));
  if (hits.length) {
    score += Math.min(hits.length, 3);
    reasons.push(hits.length + " keyword hit(s)");
  }

  if (salaryTarget > 0 && salaryFloor >= salaryTarget) {
    score += 2;
    reasons.push("pays at or above target");
  }

  if (preferRemote && String(j.locationType).toLowerCase() === "remote") {
    score += 2;
    reasons.push("remote");
  }

  if (needsVisa && j.visaSponsored === true) {
    score += 2;
    reasons.push("sponsors visa");
  }

  let salaryText = "";
  if (sr.min || sr.max) {
    const currency = sr.currency ? " " + sr.currency : "";
    salaryText = (sr.min && sr.max) ? (sr.min + " - " + sr.max + currency) : ((sr.min || sr.max) + currency);
    if (sr.period) salaryText = salaryText + " / " + sr.period;
  }

  results.push({
    json: {
      jobId: String(j.id || j.jobSlug || (j.jobTitle + "|" + j.companyName)),
      jobTitle: j.jobTitle,
      companyName: j.companyName || "",
      location: j.location || "",
      locationType: j.locationType || "",
      jobType: j.jobType || "",
      experienceLevel: j.experienceLevel || "",
      salary: salaryText,
      datePosted: j.datePosted || "",
      applyUrl: j.applicationLink || j.jobBoardLink || j.companyWebsite || "",
      score: score,
      whyItMatched: reasons.length ? reasons.join(", ") : "matched your search"
    }
  });
}

results.sort((a, b) => b.json.score - a.json.score);
return results;

