const jobs = $input.all().map(i => i.json);
const today = $now.toFormat("cccc, LLLL d, yyyy");
const count = jobs.length;
const noun = count === 1 ? "job" : "jobs";

const meta = (j) => [j.location, j.locationType, j.jobType, j.experienceLevel, j.salary].filter(Boolean).join(" \u00b7 ");

const slackLines = jobs.map(j => {
  const head = j.applyUrl ? ("<" + j.applyUrl + "|" + j.jobTitle + ">") : j.jobTitle;
  return "\u2022 *" + head + "* at " + j.companyName + "\n   " + meta(j);
});

const htmlRows = jobs.map(j => {
  const link = j.applyUrl || "#";
  return "<tr><td style='padding:12px 0;border-bottom:1px solid #eeeeee;'>"
    + "<a href='" + link + "' style='font-weight:bold;color:#1a73e8;text-decoration:none;font-size:15px;'>" + j.jobTitle + "</a><br>"
    + "<span style='color:#333333;'>" + j.companyName + "</span><br>"
    + "<span style='color:#777777;font-size:13px;'>" + meta(j) + "</span>"
    + "</td></tr>";
});

const digest = ":newspaper: *Daily Jobs Digest - " + today + "*\n"
  + count + " new " + noun + " matched your search in the last 24 hours\n\n"
  + slackLines.join("\n\n");

const digestHtml = "<div style='font-family:Arial,Helvetica,sans-serif;max-width:640px;'>"
  + "<h2 style='margin-bottom:4px;'>Daily Jobs Digest</h2>"
  + "<p style='color:#777777;margin-top:0;'>" + today + " &middot; " + count + " new " + noun + "</p>"
  + "<table style='width:100%;border-collapse:collapse;'>" + htmlRows.join("") + "</table>"
  + "</div>";

return [{ json: { digest: digest, digestHtml: digestHtml, subject: "Daily Jobs Digest: " + count + " new " + noun, jobCount: count } }];
